import{_ as e,o as d,c as o,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"개인정보처리방침","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/privacy"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/privacy"}],["meta",{"property":"og:title","content":"개인정보처리방침"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),r={name:"privacy.md"};function c(i,t,n,h,l,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="개인정보처리방침" tabindex="-1">개인정보처리방침 <a class="header-anchor" href="#개인정보처리방침" aria-label="Permalink to &quot;개인정보처리방침&quot;">​</a></h1><p>프루퍼 주식회사(이하 &quot;회사&quot;)는 dira(엔진과 앱을 합친 이름)를 운영하며 아래와 같이 개인정보를 처리합니다.</p><h2 id="_1-처리-목적" tabindex="-1">1. 처리 목적 <a class="header-anchor" href="#_1-처리-목적" aria-label="Permalink to &quot;1. 처리 목적&quot;">​</a></h2><p>앱(<code>dira teams</code>)을 실제로 켜는 사람이 있는지, 온보딩 중 어디서 멈추는지를 봅니다. 설치가 몇 벌 도는지, 화면 동작 몇 가지를 셉니다. 누가 쓰는지는 회사도 모릅니다.</p><p>웹사이트에는 상담 위젯이 하나 붙어 있습니다. 그 창으로 들어온 문의에 답하고 같은 사람이 다시 물어 올 때 앞의 대화를 이어 봅니다.</p><h2 id="_2-처리-항목" tabindex="-1">2. 처리 항목 <a class="header-anchor" href="#_2-처리-항목" aria-label="Permalink to &quot;2. 처리 항목&quot;">​</a></h2><p>앱은 로그인도 계정도 없습니다. 사람을 식별하지 않고 설치 한 벌을 익명으로 셉니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>무엇</th><th>어디 사나</th></tr></thead><tbody><tr><td>설치 식별자(<code>install_id</code>)</td><td>이 맥의 이 설치 한 벌을 가리키는 무작위 UUID. GA4 <code>client_id</code>로 보냅니다</td><td><code>~/.config/dira/analytics.json</code></td></tr><tr><td>세션 식별자(<code>session_id</code>)</td><td>앱을 켜서 쓰는 한 번. GA4 <code>session_id</code>로 보냅니다</td><td>서버 프로세스 메모리(파일에 남지 않습니다)</td></tr></tbody></table><p>두 값 다 사람 이름·이메일·계정과 연결되지 않습니다. 이 식별자에 실려 나가는 이벤트는 아래 8종뿐입니다.</p><table tabindex="0"><thead><tr><th>이벤트</th><th>언제</th><th>파라미터</th></tr></thead><tbody><tr><td><code>app_open</code></td><td>사용자 세션이 시작될 때(첫 이벤트 앞·30분 무활동 뒤 재시작)</td><td><code>app_version</code>, <code>shell</code>(<code>desktop</code>|<code>browser</code>)</td></tr><tr><td><code>screen_view</code></td><td>화면 진입</td><td><code>screen</code>(<code>root</code>|<code>board</code>|<code>ticket</code>|<code>workers</code>|<code>personas</code>|<code>protocols</code>|<code>home</code>)</td></tr><tr><td><code>project_add</code></td><td>프로젝트가 하나 늘었을 때</td><td><code>method</code>(<code>create</code>|<code>register</code>)</td></tr><tr><td><code>worker_create</code></td><td>워커 생성 성공</td><td><code>engine</code>(<code>claude</code>|<code>codex</code>|<code>other</code>), <code>cron_ok</code>(bool)</td></tr><tr><td><code>ticket_create</code></td><td>티켓 발행·요구 접수 성공</td><td><code>kind</code>(<code>work</code>|<code>request</code>|<code>feedback</code>)</td></tr><tr><td><code>answer_submit</code></td><td>답변 왕복의 답을 사람이 썼을 때</td><td>없음</td></tr><tr><td><code>feedback_submit</code></td><td>의견 보내기 폼에서 보내기를 눌렀을 때</td><td>없음</td></tr><tr><td><code>analytics_off</code></td><td>통계를 끌 때(끄기 직전 마지막 한 번)</td><td>없음</td></tr></tbody></table><p>값은 개수·불리언·미리 정한 enum뿐입니다. 자유 입력은 어디에도 없습니다.</p><p>웹사이트(이 페이지가 속한 <code>dira.proofer.tech</code>)는 Vercel Analytics로 방문 집계값을 쿠키 없이 모읍니다. 방문자 개인을 식별하지 않는 페이지뷰·경로 단위 집계입니다.</p><p>이 페이지를 열면 상담 위젯이 채널코퍼레이션 서버로 요청을 보냅니다. 채팅창을 한 번도 열지 않아도 접속 기록이 남습니다. IP 주소, 그 주소로 짐작하는 접속 지역, 접속 일시, 브라우저와 기기 정보입니다.</p><p>채팅창을 열면 거기 적은 것이 더해집니다. 문의 내용, 그리고 답장을 받으려고 스스로 남긴 이름이나 연락처입니다. 이쪽은 자유 입력이라 무엇이 들어갈지를 회사가 미리 정해 두지 않습니다. 쓰고 싶지 않은 것은 빼고 물어도 됩니다.</p><h2 id="_3-처리하지-않는-항목" tabindex="-1">3. 처리하지 않는 항목 <a class="header-anchor" href="#_3-처리하지-않는-항목" aria-label="Permalink to &quot;3. 처리하지 않는 항목&quot;">​</a></h2><p>아래는 어떤 이벤트의 어떤 파라미터에도 들어가지 않습니다.</p><p>파일 경로 · 프로젝트 이름 · 큐 루트 · 티켓 해시 · 티켓 제목 · 티켓 본문 · 페르소나 이름 · 에이전트 출력 · 계정 정보 · 소스 코드.</p><p>이것은 문구가 아니라 이행 수단입니다. 이벤트와 그 파라미터를 정의하는 <a href="https://github.com/proofer-tech/dira/blob/master/apps/teams/lib/analytics.ts" target="_blank" rel="noreferrer"><code>Events</code> 타입</a>이 표를 닫고 있어서, 이 표에 없는 이름이나 파라미터는 컴파일이 거부합니다. 코드가 새 값을 몰래 실어 보낼 길이 없습니다.</p><p>여기까지는 앱이 보내는 이벤트 이야기입니다. 웹사이트 상담 위젯은 앱을 거치지 않고 방문자 브라우저에서 바로 나가므로 이 표에 들어가지 않습니다. 위젯에 무엇이 실리는지는 2항에 있습니다.</p><h2 id="_4-쿠키" tabindex="-1">4. 쿠키 <a class="header-anchor" href="#_4-쿠키" aria-label="Permalink to &quot;4. 쿠키&quot;">​</a></h2><p>앱은 쿠키를 심지 않습니다. <code>gtag.js</code>를 쓰지 않고 서버가 Google Analytics 4의 Measurement Protocol로 직접 이벤트를 보냅니다. 웹사이트가 쓰는 Vercel Analytics도 쿠키리스입니다.</p><p>쿠키는 웹사이트에 한 벌 있습니다. 상담 위젯이 심는 <code>_dd_s_v2</code>입니다. 채널톡은 이 값으로 위젯의 오류와 성능을 봅니다. 브라우저 세션 한 번을 구분할 뿐 이름이나 계정과 연결되지 않습니다. 채팅창을 한 번도 열지 않아도 이 쿠키는 생깁니다. 위젯째로 막으려면 브라우저에서 <code>cdn.channel.io</code>와 <code>api.channel.io</code>로 가는 요청을 차단하면 됩니다.</p><h2 id="_5-보유-및-파기" tabindex="-1">5. 보유 및 파기 <a class="header-anchor" href="#_5-보유-및-파기" aria-label="Permalink to &quot;5. 보유 및 파기&quot;">​</a></h2><p>GA4가 잡는 보존 기간은 대상마다 다릅니다(2026-08-02 GA4 콘솔 확인값).</p><table tabindex="0"><thead><tr><th>대상</th><th>보존 기간</th></tr></thead><tbody><tr><td>이벤트 데이터 — 이벤트 8종과 그 파라미터</td><td>2개월</td></tr><tr><td>사용자 데이터 — 설치 식별자에 연결된 데이터</td><td>14개월</td></tr></tbody></table><p>로컬에 남는 <code>~/.config/dira/analytics.json</code>은 회사 쪽이 아니라 각자의 맥에 있습니다. 파일을 지우면 그 즉시 소멸하고, 다음 실행에서 새 설치 식별자가 발급됩니다.</p><h2 id="_6-처리위탁-및-국외이전" tabindex="-1">6. 처리위탁 및 국외이전 <a class="header-anchor" href="#_6-처리위탁-및-국외이전" aria-label="Permalink to &quot;6. 처리위탁 및 국외이전&quot;">​</a></h2><table tabindex="0"><thead><tr><th>수탁자</th><th>업무</th><th>이전 국가</th></tr></thead><tbody><tr><td>Google LLC</td><td>GA4 이벤트 수집·분석</td><td>미국</td></tr><tr><td>Vercel Inc.</td><td>웹사이트 호스팅·방문 집계</td><td>미국</td></tr><tr><td>주식회사 채널코퍼레이션</td><td>상담 위젯 문의 응대</td><td>—</td></tr></tbody></table><p>채널코퍼레이션은 국내 법인이고 채널톡이 도는 클라우드도 AWS 서울 리전입니다. 그래서 이 위탁에는 국외로 나가는 것이 없습니다. 다만 그 회사도 자기 업무 일부를 국외에 다시 맡깁니다. 그 내역은 <a href="https://channel.io/kr/privacy" target="_blank" rel="noreferrer">채널톡 개인정보처리방침</a> 6항과 7항에 있습니다(2026-08-04 확인).</p><p>위 셋 외에 개인정보를 제3자에게 제공하지 않습니다.</p><h2 id="_7-정보주체의-권리" tabindex="-1">7. 정보주체의 권리 <a class="header-anchor" href="#_7-정보주체의-권리" aria-label="Permalink to &quot;7. 정보주체의 권리&quot;">​</a></h2><ul><li><strong>끄기</strong> — 앱 우측 위 톱니바퀴 → <code>설정</code> 다이얼로그 세 번째 구획. 기본은 켜짐이고 버튼 하나로 끕니다. 끄면 그 순간부터 아무 이벤트도 나가지 않습니다.</li><li><strong>삭제</strong> — <code>~/.config/dira/analytics.json</code>을 지우면 설치 식별자가 함께 사라집니다. 이전 통계와 이어지지 않는 새 설치로 다시 잡힙니다.</li><li><strong>문의</strong> — info@proofer.tech</li></ul><h2 id="_8-개인정보-보호책임자" tabindex="-1">8. 개인정보 보호책임자 <a class="header-anchor" href="#_8-개인정보-보호책임자" aria-label="Permalink to &quot;8. 개인정보 보호책임자&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>성명</td><td>임한솔(대표)</td></tr><tr><td>연락처</td><td>info@proofer.tech</td></tr></tbody></table><h2 id="_9-사업자-정보" tabindex="-1">9. 사업자 정보 <a class="header-anchor" href="#_9-사업자-정보" aria-label="Permalink to &quot;9. 사업자 정보&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>상호</td><td>프루퍼 주식회사</td></tr><tr><td>대표자</td><td>임한솔</td></tr><tr><td>사업자등록번호</td><td>337-81-03650</td></tr><tr><td>주소</td><td>서울 강남구 강남대로112길 47, 2층 421A</td></tr><tr><td>문의</td><td>info@proofer.tech</td></tr></tbody></table><h2 id="_10-시행일" tabindex="-1">10. 시행일 <a class="header-anchor" href="#_10-시행일" aria-label="Permalink to &quot;10. 시행일&quot;">​</a></h2><p>이 방침은 2026-08-04부터 시행합니다. 이번 개정은 웹사이트에 붙은 상담 위젯 한 축을 다룹니다. 앱(<code>dira teams</code>)이 무엇을 보내고 무엇을 안 보내는지는 직전 판(2026-08-02 시행)에서 한 줄도 갈리지 않았습니다.</p>',38)])])}const _=e(r,[["render",c]]);export{b as __pageData,_ as default};
